/* PawLife offline service worker — generated by web/build.js. Do not edit. */
'use strict'
const VERSION = "6dece018d10e"
const CACHE = 'pawlife-' + VERSION
const PRECACHE = ["./","./app.js","./app.css","./manifest.webmanifest","./icon-180.png","./icon-192.png","./icon-512.png"]
const SCOPE_PATH = new URL('./', self.location.href).pathname

// a redirected response can't answer a navigation (Safari: "has redirections") → store a clean copy
function clean(res) {
  if (!res.redirected) return Promise.resolve(res)
  return res.blob().then((body) => new Response(body, { status: res.status, statusText: res.statusText, headers: res.headers }))
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then((cache) => Promise.all(PRECACHE.map((u) => {
        const req = new Request(u, { cache: 'reload' })
        return fetch(req).then((res) => {
          if (!res || !res.ok) throw new Error('precache ' + u + ' → HTTP ' + (res && res.status))
          return clean(res).then((r) => cache.put(req, r))
        })
      })))
      .then(() => self.skipWaiting())
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.indexOf('pawlife-') === 0 && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  )
})

self.addEventListener('message', (event) => {
  if (event.data === 'SKIP_WAITING') self.skipWaiting()
})

// own cache first (an older one may still exist mid-update), then any; storage errors → miss
function fromCache(req, opts) {
  return caches.open(CACHE)
    .then((c) => c.match(req, opts))
    .then((r) => r || caches.match(req, opts))
    .catch(() => undefined)
}

self.addEventListener('fetch', (event) => {
  const req = event.request
  if (req.method !== 'GET') return
  let url
  try {
    url = new URL(req.url)
  } catch (e) {
    return
  }
  if (url.origin !== self.location.origin) return // DashScope / PubMed / anything cross-origin: untouched
  if (req.mode === 'navigate') {
    const shell = url.pathname === SCOPE_PATH || url.pathname === SCOPE_PATH + 'index.html'
    event.respondWith(
      shell
        ? fromCache('./').then((r) => r || fetch(req))
        : fetch(req).catch(() => fromCache(req, { ignoreSearch: true }).then((r) => r || fromCache('./')).then((r) => r || Response.error()))
    )
    return
  }
  event.respondWith(fromCache(req, { ignoreSearch: true }).then((r) => r || fetch(req)))
})
